#![cfg(unix)]

//! A fixed group aligns its members after the cascade first visits them, so dependency rewrites and range rejections
//! must follow the aligned versions, never the provisional per-member bumps.

#[path = "common/release_harness.rs"]
mod release_harness;

use std::{fs, path::Path};

use release_harness::*;

/// `lib-a` (released, 1.0.0) and `lib-b` (never released, 2.0.0) share a fixed group; `app` depends on `lib-b`.
fn cargo_workspace(requirement: &str) -> tempfile::TempDir {
    let dir = tempfile::tempdir().unwrap();
    let root = dir.path();
    callisto_fixtures::git::init_repo(root);
    fs::write(
        root.join("Cargo.toml"),
        "[workspace]\nmembers = [\"crates/*\"]\nresolver = \"2\"\n",
    )
    .unwrap();
    for (name, version, extra) in [
        ("lib-a", "1.0.0", String::new()),
        ("lib-b", "2.0.0", String::new()),
        (
            "app",
            "0.1.0",
            format!("\n[dependencies]\nlib-b = {{ path = \"../lib-b\", version = \"{requirement}\" }}\n"),
        ),
    ] {
        let dir = root.join(format!("crates/{name}"));
        fs::create_dir_all(dir.join("src")).unwrap();
        fs::write(
            dir.join("Cargo.toml"),
            format!("[package]\nname = \"{name}\"\nversion = \"{version}\"\nedition = \"2021\"\n{extra}"),
        )
        .unwrap();
        fs::write(dir.join("src/lib.rs"), "\n").unwrap();
    }
    git(root, &["add", "."]);
    git(root, &["commit", "-q", "-m", "workspace"]);
    git(root, &["tag", "lib-a@1.0.0"]);
    let init = callisto(root, &["init", "--yes", "--versioning", "independent", "--no-workflow"]);
    assert!(init.status.success(), "{}", String::from_utf8_lossy(&init.stderr));
    let config = fs::read_to_string(root.join("callisto.toml")).unwrap();
    fs::write(
        root.join("callisto.toml"),
        format!("{config}\n[[fixed-group]]\nname = \"pair\"\nmembers = [\"cargo/lib-a\", \"cargo/lib-b\"]\n"),
    )
    .unwrap();
    git(root, &["add", "."]);
    git(root, &["commit", "-q", "-m", "configure callisto"]);
    dir
}

fn add_changeset(root: &Path, package: &str, bump: &str) {
    let out = callisto(
        root,
        &["add", "--package", &format!("{package}:{bump}"), "--summary", "change"],
    );
    assert!(out.status.success(), "{}", String::from_utf8_lossy(&out.stderr));
    git(root, &["add", "."]);
    git(root, &["commit", "-q", "-m", "changeset"]);
}

#[test]
fn probe() {
    for requirement in ["2.0.0", "=2.0.0", ">=1.0.0, <=2.0.0", ">=1.0.0, <3.0.0"] {
        let dir = cargo_workspace(requirement);
        let root = dir.path();
        add_changeset(root, "cargo/lib-b", "patch");
        let out = callisto(root, &["version"]);
        eprintln!(
            "== {requirement}: ok={}\n{}\n{}\n{}",
            out.status.success(),
            String::from_utf8_lossy(&out.stderr),
            fs::read_to_string(root.join("crates/app/Cargo.toml")).unwrap(),
            fs::read_to_string(root.join("crates/lib-b/Cargo.toml")).unwrap(),
        );
    }
}

